import unittest
from config import merge_config

class ConfigTests(unittest.TestCase):
    def test_inputs_unchanged(self):
        base = {"enabled": True, "retries": 3}
        overrides = {"enabled": False, "retries": 0}
        self.assertEqual(merge_config(base, overrides), {"enabled": False, "retries": 0})
        self.assertEqual(base, {"enabled": True, "retries": 3})
        self.assertEqual(overrides, {"enabled": False, "retries": 0})
    def test_existing_key(self):
        self.assertEqual(merge_config({"a": 1}, {"b": 2}), {"a": 1, "b": 2})
